def choose_move(observation):
    dx = 0
    dy = 0

    if not isinstance(observation, dict):
        return [0, 0]

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    self_pos = observation.get("self_position", {})
    opp_pos = observation.get("opponent_position", {})

    x = self_pos.get("x", 0)
    y = self_pos.get("y", 0)

    # Stay within bounds
    def in_bounds(nx, ny):
        return 0 <= nx < gw and 0 <= ny < gh

    # Simple heuristic: move away from opponent if too close, else toward center
    ox = opp_pos.get("x", None)
    oy = opp_pos.get("y", None)
    if ox is not None and oy is not None:
        if abs(ox - x) <= 1 and abs(oy - y) <= 1:
            if ox > x:
                dx = -1
            elif ox < x:
                dx = 1
            else:
                dx = 0
            if oy > y:
                dy = -1
            elif oy < y:
                dy = 1
            else:
                dy = 0
            nx, ny = x + dx, y + dy
            if not in_bounds(nx, ny):
                dx, dy = 0, 0
            return [dx, dy]

    # Move toward center if possible
    cx = gw // 2
    cy = gh // 2
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1
    else:
        dx = 0
    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1
    else:
        dy = 0

    nx, ny = x + dx, y + dy
    if not in_bounds(nx, ny):
        dx, dy = 0, 0

    return [dx, dy]
